// Translated from Ghostty's src/build/Config.zig ReleaseChannel declaration.
module buildcfg

import build_meta

pub const linux_executable_name = 'witty'
pub const cli_command = $if linux { linux_executable_name } $else { 'ghostty' }

// ReleaseChannel determines the release channel for this build.
pub enum ReleaseChannel as u8 {
	// Tip/nightly release (built from latest source)
	tip
	// Stable release
	stable
}

pub const release_channel = if build_meta.release_channel == 'stable' {
	ReleaseChannel.stable
} else {
	ReleaseChannel.tip
}

// Build feature flags generated by Ghostty's build options. V exposes the
// equivalent custom compile-time defines through `-d <name>`.
pub const flatpak = $if flatpak ? { true } $else { false }
pub const snap = $if snap ? { true } $else { false }

// Debug and ReleaseSafe both retain source runtime checks. The translated
// build driver selects ReleaseSafe without V's -prod (which removes assert).
pub const runtime_safety = $if prod { false } $else { true }
pub const slow_runtime_safety = $if prod {
	false
} $else $if release_safe ? {
	false
} $else {
	true
}

pub const mode_string = $if release_safe ? {
	'ReleaseSafe'
} $else $if release_small ? {
	'ReleaseSmall'
} $else $if prod {
	'ReleaseFast'
} $else {
	'Debug'
}

// Ghostty's main build enables Oniguruma and synthesizes both terminal
// features from that one option. `-d no_oniguruma` models the reduced
// libghostty-vt build, whose source build explicitly disables it.
pub const oniguruma = $if no_oniguruma ? { false } $else { true }
pub const kitty_graphics = oniguruma
pub const tmux_control_mode = oniguruma

// Config.zig enables gettext on Darwin and GNU-libc Unix targets. An explicit
// build option overrides that default, including identity canonicalization.
const default_i18n = $if macos || ios {
	true
} $else $if (linux || freebsd) && glibc {
	true
} $else {
	false
}
pub const i18n = $if no_i18n ? {
	false
} $else $if i18n ? {
	true
} $else {
	default_i18n
}
